'use client';

import * as React from 'react';
import { cn } from '@/lib/utils';

/** User sentiment for an AI response. */
export type FeedbackRating = 'up' | 'down';

export interface MessageActionsProps {
  /**
   * Visibility rule:
   * - 'always': always visible (default)
   * - 'on-hover': fades in when the parent message is hovered/focused
   *   (add the `group` class to the parent element)
   * - 'not-last': like 'on-hover', intended for non-latest messages
   */
  autohide?: 'always' | 'on-hover' | 'not-last';
  /**
   * Content to copy. Omit to hide the copy action, or pass a getter when
   * the content lives outside this component.
   */
  content?: string;
  /** Called after the user copies the message; receives the copied text. */
  onCopy?: (content: string) => void;
  /** Called with the selected rating; selecting the same rating clears it (passes undefined). */
  onFeedback?: (rating: FeedbackRating | undefined) => void;
  /** Called when the user requests a regenerated response; omit to hide the action. */
  onRegenerate?: () => void;
  labels?: {
    copy?: string;
    copied?: string;
    thumbUp?: string;
    thumbDown?: string;
    regenerate?: string;
  };
  className?: string;
}

const MessageActions = React.forwardRef<HTMLDivElement, MessageActionsProps>(
  (
    { content, onCopy, onFeedback, onRegenerate, autohide = 'always', labels, className, ...props },
    ref
  ) => {
    const [copied, setCopied] = React.useState(false);
    const [rating, setRating] = React.useState<FeedbackRating | undefined>();

    const t = {
      copy: labels?.copy ?? 'Copy',
      copied: labels?.copied ?? 'Copied',
      thumbUp: labels?.thumbUp ?? 'Good response',
      thumbDown: labels?.thumbDown ?? 'Bad response',
      regenerate: labels?.regenerate ?? 'Regenerate',
    };

    const handleCopy = async () => {
      if (!content) return;
      try {
        await navigator.clipboard.writeText(content);
      } catch {
        // Clipboard API may be unavailable (insecure context); still notify so consumers can react.
      }
      setCopied(true);
      window.setTimeout(() => setCopied(false), 2000);
      onCopy?.(content);
    };

    const handleRating = (next: FeedbackRating) => {
      const updated = rating === next ? undefined : next;
      setRating(updated);
      onFeedback?.(updated);
    };

    const actionButton =
      'rounded px-1.5 py-0.5 text-xs transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring';
    const actionButtonIdle =
      'text-muted-foreground hover:bg-accent hover:text-accent-foreground';

    return (
      <div
        ref={ref}
        role="toolbar"
        aria-label="Message actions"
        className={cn(
          'flex items-center gap-1 mt-2',
          autohide !== 'always' &&
            'opacity-0 transition-opacity focus-within:opacity-100 group-hover:opacity-100 motion-reduce:opacity-100',
          className
        )}
        {...props}
      >
        {content !== undefined && (
          <button type="button" onClick={handleCopy} className={cn(actionButton, actionButtonIdle)}>
            {copied ? t.copied : t.copy}
          </button>
        )}

        <button
          type="button"
          onClick={() => handleRating('up')}
          aria-label={t.thumbUp}
          aria-pressed={rating === 'up'}
          className={cn(
            actionButton,
            rating === 'up' ? 'text-primary' : actionButtonIdle
          )}
        >
          👍
        </button>

        <button
          type="button"
          onClick={() => handleRating('down')}
          aria-label={t.thumbDown}
          aria-pressed={rating === 'down'}
          className={cn(
            actionButton,
            rating === 'down' ? 'text-destructive' : actionButtonIdle
          )}
        >
          👎
        </button>

        {onRegenerate && (
          <button type="button" onClick={onRegenerate} className={cn(actionButton, actionButtonIdle)}>
            {t.regenerate}
          </button>
        )}
      </div>
    );
  }
);
MessageActions.displayName = 'MessageActions';

export { MessageActions };

{
  "id": "message-actions",
  "name": "MessageActions",
  "tier": "atom",
  "description": "Feedback toolbar for an AI response: copy to clipboard, thumbs up/down rating, and regenerate. Every action is a callback; the component holds no conversation state.",
  "designIntent": "Collect user trust signals (copy, rating, regeneration) with minimal API surface; consumers own what happens after each action.",
  "props": [
    { "name": "content", "type": "string", "required": false, "description": "Text to copy; omit to hide the copy action." },
    { "name": "onCopy", "type": "(content: string) => void", "required": false, "description": "Called after copy with the copied text." },
    { "name": "onFeedback", "type": "(rating: 'up' | 'down' | undefined) => void", "required": false, "description": "Rating callback; selecting the active rating again passes undefined." },
    { "name": "onRegenerate", "type": "() => void", "required": false, "description": "Regeneration request; omit to hide the action." },
    { "name": "labels", "type": "{ copy?, copied?, thumbUp?, thumbDown?, regenerate? }", "required": false, "description": "Overrides for all visible labels; enables localization." }
  ],
  "examples": [
    {
      "title": "Full feedback bar",
      "code": "<MessageActions content={message.content} onCopy={copy} onFeedback={(r) => track(r)} onRegenerate={regen} />"
    },
    {
      "title": "Ratings only",
      "code": "<MessageActions onFeedback={(r) => save(r)} />"
    }
  ],
  "antiPatterns": [
    { "title": "Do not place MessageActions inside the message text flow", "explanation": "Render it below the Message bubble so actions remain visually and semantically separate from content." }
  ],
  "accessibility": [
    { "feature": "Toolbar semantics", "implementation": "Root has role=toolbar with an aria-label." },
    { "feature": "Toggle state", "implementation": "Rating buttons expose aria-pressed so screen readers announce selection." },
    { "feature": "Icon buttons", "implementation": "All icon-only controls have accessible labels; labels are localizable." }
  ],
  "package": "@slipstream-ui/ai",
  "importPath": "@slipstream-ui/ai",
  "version": "0.0.1"
}
